  "Pset_ProfileMechanical": {
    label: "Property Set: Profile Mechanical",
    description: "This is a collection of mechanical properties that are applicable to virtually all profile classes. Most of these properties are especially used in structural analysis.",
    art: "PSET_PROFILEDRIVEN",
    applicableTo: ["IFCPROFILEDEF"],
    props: [
      {"name": "MassPerLength", "type": "IfcMassPerLengthMeasure", "description": "Mass per length, i.e. mass of a beam with a unit length of extrusion. For example measured in kg/m."},
      {"name": "CrossSectionArea", "type": "IfcAreaMeasure", "description": "Total area of the cross section (or profile) of the object."},
      {"name": "Perimeter", "type": "IfcPositiveLengthMeasure", "description": "Perimeter of the object. Perimeter of the profile for calculating the surface area. For example measured in mm."},
      {"name": "MinimumPlateThickness", "type": "IfcPositiveLengthMeasure", "description": "This value may be needed for stress analysis and to handle buckling problems."},
      {"name": "MaximumPlateThickness", "type": "IfcPositiveLengthMeasure", "description": "This value may be needed for stress analysis and to handle buckling problems."},
      {"name": "CentreOfGravityInX", "type": "IfcLengthMeasure", "description": "Location of the profile's centre of gravity (geometric centroid), measured along xp."},
      {"name": "CentreOfGravityInY", "type": "IfcLengthMeasure", "description": "Location of the profile's centre of gravity (geometric centroid), measured along yp."},
      {"name": "ShearCentreZ", "type": "IfcLengthMeasure", "description": "Location of the profile's shear centre, measured along zs."},
      {"name": "ShearCentreY", "type": "IfcLengthMeasure", "description": "Location of the profile's shear centre, measured along ys."},
      {"name": "MomentOfInertiaY", "type": "IfcMomentOfInertiaMeasure", "description": "Moment of inertia about ys (second moment of area, about ys). For example measured in mm4."},
      {"name": "MomentOfInertiaZ", "type": "IfcMomentOfInertiaMeasure", "description": "Moment of inertia about zs (second moment of area, about zs). For example measured in mm4"},
      {"name": "MomentOfInertiaYZ", "type": "IfcMomentOfInertiaMeasure", "description": "Moment of inertia about ys and zs (product moment of area). For example measured in mm4."},
      {"name": "TorsionalConstantX", "type": "IfcMomentOfInertiaMeasure", "description": "Torsional constant about xs. For example measured in mm4."},
      {"name": "WarpingConstant", "type": "IfcWarpingConstantMeasure", "description": "Warping constant of the profile for torsional action. For example measured in mm6."},
      {"name": "ShearDeformationAreaZ", "type": "IfcAreaMeasure", "description": "Area of the profile for calculating the shear deformation due to a shear force parallel to zs."},
      {"name": "ShearDeformationAreaY", "type": "IfcAreaMeasure", "description": "Area of the profile for calculating the shear deformation due to a shear force parallel to ys."},
      {"name": "MaximumSectionModulusY", "type": "IfcSectionModulusMeasure", "description": "Bending resistance about the ys axis at the point with maximum zs ordinate. For example measured in mm³."},
      {"name": "MinimumSectionModulusY", "type": "IfcSectionModulusMeasure", "description": "Bending resistance about the ys axis at the point with minimum zs ordinate. For example measured in mm³."},
      {"name": "MaximumSectionModulusZ", "type": "IfcSectionModulusMeasure", "description": "Bending resistance about the zs axis at the point with maximum ys ordinate. For example measured in mm³."},
      {"name": "MinimumSectionModulusZ", "type": "IfcSectionModulusMeasure", "description": "Bending resistance about the zs axis at the point with minimum ys ordinate. For example measured in mm³."},
      {"name": "TorsionalSectionModulus", "type": "IfcSectionModulusMeasure", "description": "Torsional resistance (about xs). For example measured in mm³."},
      {"name": "ShearAreaZ", "type": "IfcAreaMeasure", "description": "Area of the profile for calculating the shear stress due to shear force parallel to the section analysis axis zs."},
      {"name": "ShearAreaY", "type": "IfcAreaMeasure", "description": "Area of the profile for calculating the shear stress due to shear force parallel to the section analysis axis ys."},
      {"name": "PlasticShapeFactorY", "type": "IfcPositiveRatioMeasure", "description": "Ratio of plastic versus elastic bending moment capacity about the section analysis axis ys. A dimensionless value."},
      {"name": "PlasticShapeFactorZ", "type": "IfcPositiveRatioMeasure", "description": "Ratio of plastic versus elastic bending moment capacity about the section analysis axis zs. A dimensionless value."},
    ],
  },
